package com.ams.controller;
import com.ams.dto.*; import com.ams.service.PaymentService; import jakarta.validation.Valid; import org.springframework.http.ResponseEntity; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/payments") @PreAuthorize("hasRole('CUSTOMER')") public class PaymentController {private final PaymentService service; public PaymentController(PaymentService service){this.service=service;} @PostMapping("/membership") public ResponseEntity<PaymentResponse> pay(@Valid @RequestBody MembershipPaymentRequest r){return ResponseEntity.ok(service.pay(r));} @PostMapping("/membership/{paymentId}/confirm") public ResponseEntity<PaymentResponse> confirm(@PathVariable Integer paymentId){return ResponseEntity.ok(service.confirmUpi(paymentId));} @GetMapping("/my") public ResponseEntity<List<PaymentResponse>> mine(){return ResponseEntity.ok(service.getMyPayments());}}
